namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage3; class alist extends cloudStorage3 { var $cookie = null; var $args; var $authorization; var $version; public function init() { $this->custom_upload_dir = $this->options->cloud_storage_alist_custom_upload_dir; $this->folder = $this->options->cloud_storage_alist_folder; $this->version = $this->options->cloud_storage_alist_version; $this->homepage = $this->options->cloud_storage_alist_homepage; $this->authorization = $this->options->cloud_storage_alist_authorization; $this->host = parse_url($this->homepage, PHP_URL_HOST); $this->sync_delete = $this->options->cloud_storage_alist_sync_delete; $this->silent_scanning = $this->options->cloud_storage_alist_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_alist_delete_attachment_after_synced; add_filter( 'qqworld-collector-cloud-storage-settings', array($this, 'cloud_storage_settings') ); } public function cloud_storage_settings($values) { if (isset($values[$this->guid])) { $values[$this->guid]['homepage'] = preg_replace('/\/*$/i', '', trim($values[$this->guid]['homepage'])); if ($values[$this->guid]['homepage']) $this->create_table(); } return $values; } public function access_service() { if ($this->enabled && $this->is_current && !$this->accessed) { if ($this->authorization) { switch ($this->version) { case 3: $url = $this->homepage . '/api/public/settings'; break; case 2: default: $url = $this->homepage . '/api/admin/settings?group=0'; break; } $this->args = array( 'sslverify' => false, 'headers' => array( 'authorization' => $this->authorization, 'accept' => 'application/json, text/plain, */*', ) ); $response = wp_remote_get($url, $this->args); $body = wp_remote_retrieve_body($response); $body = json_decode($body, true); if ($body['code'] == 200) { $this->accessed = true; } else { if ($body['message']) { print '<div class="error"><p>' . $body['message'] . '</p></div>'; } else { do_action( 'qqworld-collector-log', $this->log_id, 'alist login Error:', print_r($body, true) ); } } } } } public function make_dir($path) { switch ($this->version) { case 3: $url = $this->homepage . '/api/fs/get'; break; case 2: default: $url = $this->homepage . '/api/public/path'; break; } $args = array( 'sslverify' => false, 'headers' => array( 'content-type' => 'application/json;charset=UTF-8' ), 'body' => '{"path":"/'.$path.'","password":"","page":1,"per_page":0,"page_size":false}' ); $response = wp_remote_post($url, $args); $body = wp_remote_retrieve_body($response); $json = json_decode($body, true); if ($json['code'] != 200) { switch ($this->version) { case 3: $url = $this->homepage . '/api/fs/mkdir'; break; case 2: default: $url = $this->homepage . '/api/admin/mkdir'; break; } $dir_args = $this->args; $paths = array_filter(explode('/', $path)); $temp_p = ''; foreach ($paths as $path) { $dir_args = $this->args; $temp_p .= '/' . $path; $dir_args['body'] = '{"path":"'.$temp_p.'"}'; $dir_args['headers']['content-type'] = 'application/json;charset=UTF-8'; $response = wp_remote_post($url, $dir_args); $body = wp_remote_retrieve_body($response); $json = json_decode($body, true); if ($json['code'] != 200) { do_action( 'qqworld-collector-log', $this->log_id, 'alist make dir Error:', $temp_p . "\n" . print_r($body,true) ); } } } } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; $external_link = apply_filters( 'qqworld-collector-cloud-storage-alist-upload', '', $destination_path, $source_path, $this ); if ($external_link) return $external_link; return false; } public function delete_object($object) { $object = preg_replace('/^\/*/i', '', $object); $this->access_service(); $path = strstr($object, '/') === false ? '' : dirname($object); $file_name = strstr($object, '/') === false ? $object : basename($object); $delete_args = $this->args; $delete_args['body'] = '{"names":["'.$file_name.'"],"path":"/'.$path.'"}'; switch ($this->version) { case 3: $url = $this->homepage . '/api/fs/remove'; $response = wp_remote_post($url, $delete_args); break; case 2: default: $delete_args['method'] = 'DELETE'; $url = $this->homepage . '/api/admin/files'; $response = wp_remote_request($url, $delete_args); break; } $response_code = wp_remote_retrieve_response_code($response); if ($response_code == 200) { $body = wp_remote_retrieve_body($response); $json = json_decode($body, true); if ($json && $json['code']==200) return true; } else { $response_message = wp_remote_retrieve_response_message($response); do_action( 'qqworld-collector-log', $this->log_id, 'ALIST Delete Request Error:', $object . ' (' . $response_code . ', ' . $response_message . ')' ); } return false; } public function add_form_fields() { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage3.php'; } public function add_could_storage_form($guid) { $this->access_service(); require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } } ?>